        "culturalNote_vi": "Văn hóa Nhật Bản tối kỵ việc nói thẳng 'Iie' (Không). Thay vào đó, việc ngập ngừng và bỏ lửng câu với từ 'chotto...' (nghĩa đen: 'hơi bị...') chính là tín hiệu ngầm từ chối cực kỳ lịch sự mà không gây mất lòng.",
        "culturalNote_en": "Japanese culture heavily avoids saying 'Iie' (No) directly. Instead, trailing off with 'chotto...' (literally 'a bit...') communicates an unmistakable polite 'No' without triggering conflict."
