        "translation_en": "In short / In other words / Bottom line",
        "situation_vi": "Đúc kết lại ý chính của câu chuyện",
        "situation_en": "Summarizing the core takeaway",
        "usageTip_vi": "Rất hay gặp trong thảo luận hoặc giải thích dài dòng: '要するに、やり直す必要がある' (Tóm lại là chúng ta phải làm lại từ đầu).",
        "usageTip_en": "Cuts right to the chase: 'Yousuruni, yarinaosu hitsuyou ga aru' (Bottom line: we gotta redo it)."
