        "situation_en": "Adding parenthetical side information",
        "usageTip_vi": "Dùng để thêm thông tin bên lề mượt mà: 'ちなみに、明日は定休日です' (Tiện đây nói luôn là ngày mai quán nghỉ nhé).",
        "usageTip_en": "Gracefully attaches extra trivia: 'Chinamini, ashita wa teikyuubi desu' (By the way, tomorrow is our regular day off)."
