          "phonetic": "ɪkˈskjuːz miː, aɪ wʊd laɪk tə ɪnˈkwaɪər ˈwɛð.ɚ ɪt ɪz ˈpɑː.sə.bəl fɔːr miː tə ˈpɝː.tʃəs wʌn aɪst ˈlɑː.teɪ...",
          "translation_vi": "Thứ lỗi cho tôi, tôi muốn hỏi thăm liệu tôi có thể mua một ly cà phê latte đá để tiêu thụ bên ngoài cơ sở được chăng?",
