        "casual": {
          "text": "아 진짜 가고 싶은데, 그날 선약이 있어서 좀 힘들 것 같아! 다음에 꼭 가자!",
          "phonetic": "A jinjja gago sipeunde, geunal seonyagi isseoseo jom himdeul geot gata! Daeume kkok gaja!",
          "translation_vi": "Á mình cũng muốn đi lắm, cơ mà hôm đó lỡ có hẹn trước mất rồi, e là khó đi được! Để lần tới tụi mình nhất định phải đi nha!",
          "translation_en": "Ah I really wanna go, but I've got prior plans that day so it might be tough! Rain check for sure!",
          "tag_vi": "Từ chối khéo ngọt ngào",
          "tag_en": "Warm Tactful Refusal"
        },
        "culturalNote_vi": "Người Hàn mở đầu bằng '진짜 가고 싶은데' (Thật lòng mình muốn đi lắm), dùng từ đệm '좀 힘들 것 같아' (E là hơi khó) và chốt bằng lời hứa '다음에 꼭 가자' (Lần sau nhất định đi nhé) để giữ trọn tình bạn.",
        "culturalNote_en": "Framing with 'I really wanted to go', softening with 'might be tough' (힘들 것 같아), and sealing with 'next time for sure' preserves social harmony."
